-- RCL concession buying reference catalog. Initial Sam's web-public prices captured in research on 2026-10-13.
-- Price is a NON-Richmond online listing, not a booked business invoice, and is not automatically inventory stock.
-- Restaurant Depot / US Foods CHEF'STORE prices remain NULL until quoted. Rerunnable.
with items as (
 select * from jsonb_to_recordset($rclcatalog$[{"sku":"water40","name":"Bottled water — Member's Mark 16.9oz","category":"water","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/Member-s-Mark-Purified-Water-16-9-fl-oz-40-pk/7874202847","pack_quantity":40,"pack_price":4.28,"suggested_sale_price":1.5,"supplier_notes":"Online reference visible for non-Richmond club. Confirm Virginia shelf price, membership, tax and cold storage."},{"sku":"cola35","name":"Coca-Cola 12oz cans","category":"soda","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/Coca-Cola-Soft-Drink-12-fl-oz-35-pk/13857469882","pack_quantity":35,"pack_price":19.48,"suggested_sale_price":2,"supplier_notes":"Online club reference only. Verify pickup-specific local price and possible soda excise/taxes."},{"sku":"cokezero35","name":"Coca-Cola Zero Sugar 12oz cans","category":"soda","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/Coca-Cola-Zero-Sugar-Soft-Drink-12-fl-oz-35-pk/13857673033","pack_quantity":35,"pack_price":19.48,"suggested_sale_price":2,"supplier_notes":"Club and online price vary."},{"sku":"gatorade24","name":"Gatorade 12oz bottles, 24 pack","category":"sports_drinks","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/gatorade-thirst-quencher-sports-drinks-core-variety-pack-12-fl-oz-24-pk/18861655035","pack_quantity":24,"pack_price":13.68,"suggested_sale_price":2.5,"supplier_notes":"Online price snapshot; inspect flavor assortment and local availability."},{"sku":"frito50","name":"Frito-Lay Favorites Mix assorted snack bags, 50","category":"chips","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/c/kp/variety-pack-snacks","pack_quantity":50,"pack_price":18.48,"suggested_sale_price":2,"supplier_notes":"Category source shows 50-pack $18.48; exact SKU can vary; compare pack weight and flavor mix before purchase."},{"sku":"doritos50","name":"Doritos Nacho Cheese 1oz bags, 50","category":"chips","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/doritos-nacho-cheese-tortilla-chips/13568051663","pack_quantity":50,"pack_price":18.98,"suggested_sale_price":2,"supplier_notes":"Online listed product. Distributor and club prices vary."},{"sku":"membersmix42","name":"Member's Mark chip variety, 42 count","category":"chips","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/mm-mix-variety-pack-42-ct-6sku/17733718161","pack_quantity":42,"pack_price":13.98,"suggested_sale_price":1.5,"supplier_notes":"Online listing; verify assortment, portion size and expiration date."},{"sku":"rice40","name":"Rice Krispies Treats variety, 40 bars","category":"snack_bars","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/Rice-Krispies-Treats-Snack-Bars-Variety-Pack-40-ct/15004119572","pack_quantity":40,"pack_price":9.98,"suggested_sale_price":1.5,"supplier_notes":"Web-listed pack; stock availability varies by club."},{"sku":"snickers48","name":"Snickers full-size 1.86oz bars, 48","category":"candy","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/Snickers-Milk-Chocolate-Candy-Bars-Full-Size-1-86-oz-48-pk/4000052431","pack_quantity":48,"pack_price":53.53,"suggested_sale_price":2.5,"supplier_notes":"Published online price snapshot; not confirmed Richmond store price."},{"sku":"skittles36","name":"Skittles 2.17oz full-size, 36","category":"candy","supplier":"Sam's Club","supplier_product_url":"https://www.samsclub.com/ip/Skittles-Original-Chewy-Candy-2-17-oz-36-pk/4000001160","pack_quantity":36,"pack_price":39.98,"suggested_sale_price":2.5,"supplier_notes":"Online price snapshot; verify local case pricing."},{"sku":"restaurantdepot_hotdogs","name":"Foodservice hot dogs — case quote","category":"hot_food","supplier":"Restaurant Depot","supplier_product_url":"https://www.restaurantdepot.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":4,"supplier_notes":"Member/branch-specific case pricing not publicly verified. Request case unit count, cost, required heating and health approval."},{"sku":"restaurantdepot_nachos","name":"Nacho cheese + chips supplies — case quote","category":"nachos","supplier":"Restaurant Depot","supplier_product_url":"https://www.restaurantdepot.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":4,"supplier_notes":"Request serving yield per case; cheese/warmers, gloves, portion boats must be included in unit cost."},{"sku":"restaurantdepot_popcorn","name":"Popcorn kernels + bags — case quote","category":"popcorn","supplier":"Restaurant Depot","supplier_product_url":"https://www.restaurantdepot.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":3,"supplier_notes":"Cost per serving requires kernels/oil/flavoring and paper containers; do not infer from bulk weight."},{"sku":"restaurantdepot_pretzel","name":"Frozen soft pretzels — case quote","category":"hot_food","supplier":"Restaurant Depot","supplier_product_url":"https://www.restaurantdepot.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":4,"supplier_notes":"Require case count, storage/reheating and equipment. Quote required."},{"sku":"chefstore_hotdogs","name":"Foodservice hot dogs — Richmond area case quote","category":"hot_food","supplier":"US Foods CHEF'STORE","supplier_product_url":"https://www.chefstore.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":4,"supplier_notes":"CHEF'STORE successor brand to Cash & Carry; local foodservice pricing and case quantity require location/quote."},{"sku":"chefstore_buns","name":"Hot dog buns — case quote","category":"hot_food","supplier":"US Foods CHEF'STORE","supplier_product_url":"https://www.chefstore.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":0.5,"supplier_notes":"Ingredient only, $0.50 illustrative allocation, not independent menu sale. Combined with hot dog in real food COGS."},{"sku":"chefstore_nachos","name":"Nacho trays, cheese and chips — wholesale quote","category":"nachos","supplier":"US Foods CHEF'STORE","supplier_product_url":"https://www.chefstore.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":4,"supplier_notes":"Quote required; case pack and per-serving cheese yield unknown."},{"sku":"chefstore_soda","name":"Soda case — CHEF'STORE quote","category":"soda","supplier":"US Foods CHEF'STORE","supplier_product_url":"https://www.chefstore.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":2,"supplier_notes":"Quote required, pack quantity unknown."},{"sku":"chefstore_water","name":"Bottled water case — CHEF'STORE quote","category":"water","supplier":"US Foods CHEF'STORE","supplier_product_url":"https://www.chefstore.com/","pack_quantity":1,"pack_price":null,"suggested_sale_price":1.5,"supplier_notes":"Quote required, pack quantity unknown."}]$rclcatalog$::jsonb)
 as x(sku text,name text,category text,supplier text,supplier_product_url text,
 pack_quantity integer,pack_price numeric,suggested_sale_price numeric,supplier_notes text)
)
insert into public.rcl_command_concession_catalog
(sku,name,category,supplier,supplier_product_url,pack_quantity,pack_price,
 suggested_sale_price,source_status,price_observed_at,retailer_location,supplier_notes)
select sku,name,category,supplier,supplier_product_url,pack_quantity,pack_price,
 suggested_sale_price,
 case when pack_price is not null then 'published_reference' else 'quote_required' end,
 case when pack_price is not null then date '2026-10-13' else null end,
 case when supplier='Sam''s Club' then 'Sam''s online listing; Virginia club shelf price unverified'
 else 'Distributor contact required; membership/case terms vary' end,
 supplier_notes
from items on conflict (sku) do nothing;
